ck']??1)?'checked':'' ?>> Manage Stock</label><label class="form-check form-check-inline"><input class="form-check-input" type="checkbox" name="allow_backorder" value="1" <?= old('allow_backorder',$product['allow_backorder']??0)?'checked':'' ?>> Allow Backorder</label></div></div></div>
